    try: outage_refund(p,bad,T0); print("FAIL")
    except BillingError as e: print("nonpositive:",e.code)
try: outage_refund(mk("authorized"),Decimal("1"),T0)
except BillingError as e: print("state:",e.code)
p=mk(); outage_refund(p,Decimal("50"),T0)
try: outage_refund(p,Decimal("40"),T0)
except BillingError as e: print("exceed:",e.code)

# idempotency
p=mk(); outage_refund(p,Decimal("8"),T0,idempotency_key="k1"); outage_refund(p,Decimal("8"),T0,idempotency_key="k1")
assert p.refunded_amount==Decimal("8.00"); print("idempotent ok")

# approval threshold
try: outage_refund(mk("captured","2000.00"),Decimal("1000.01"),T0)
except BillingError as e: print("approval:",e.code)
p=mk("captured","2000.00"); outage_refund(p,Decimal("1000.01"),T0,approved_by="mgr"); print("approved ok",p.refunded_amount)
